import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../core/services/api.service';

@Component({
  selector: 'app-admin-destinations',
  standalone: true,
  imports: [CommonModule, RouterModule, FormsModule],
  template: `
    <div class="page-header"><div class="container"><h2>Quản lý Điểm đến</h2></div></div>
    <section class="section">
      <div class="container">
        <div style="margin-bottom:1.5rem;display:flex;justify-content:space-between;align-items:center;">
          <input type="text" class="form-control" style="max-width:300px;" [(ngModel)]="search" (ngModelChange)="load()" placeholder="Tìm kiếm...">
          <a routerLink="/admin/destinations/create" class="btn btn-primary"><span class="material-icons">add</span> Thêm mới</a>
        </div>
        <div class="loading-spinner" *ngIf="loading"><div class="spinner"></div></div>
        <table class="data-table" *ngIf="!loading">
          <thead><tr><th>Tên</th><th>Tỉnh</th><th>Danh mục</th><th>Rating</th><th>Trạng thái</th><th>Hành động</th></tr></thead>
          <tbody>
            <tr *ngFor="let d of data">
              <td>{{ d.name }}</td>
              <td>{{ d.province?.name }}</td>
              <td>{{ d.category?.name }}</td>
              <td>{{ d.rating }}</td>
              <td><span class="badge" [class.badge-success]="d.isActive" [class.badge-danger]="!d.isActive">{{ d.isActive ? 'Active' : 'Inactive' }}</span></td>
              <td>
                <a [routerLink]="['/admin/destinations/edit', d.id]" class="btn btn-sm btn-outline">Sửa</a>
                <button class="btn btn-sm btn-danger" (click)="delete(d.id)">Xóa</button>
              </td>
            </tr>
          </tbody>
        </table>
        <div class="pagination" *ngIf="!loading && pagination.totalPages > 1">
          <button *ngFor="let p of pageNumbers" [class.active]="p === pagination.page" (click)="goToPage(p)">{{ p }}</button>
        </div>
      </div>
    </section>
  `
})
export class AdminDestinationsComponent implements OnInit {
  data: any[] = [];
  loading = true;
  search = '';
  pagination: any = { page: 1, limit: 20, total: 0, totalPages: 0 };
  pageNumbers: number[] = [];
  constructor(private api: ApiService) {}
  ngOnInit() { this.load(); }
  load() {
    this.loading = true;
    const params: any = { page: this.pagination.page, limit: 20 };
    if (this.search) params.search = this.search;
    this.api.getDestinations(params).subscribe(res => {
      this.data = res.data;
      this.pagination = res.pagination;
      this.pageNumbers = Array.from({length: Math.min(5, res.pagination.totalPages)}, (_, i) => i + 1);
      this.loading = false;
    }, () => { this.loading = false; });
  }
  goToPage(p: number) { this.pagination.page = p; this.load(); }
  delete(id: string) {
    if (confirm('Xác nhận xóa?')) {
      this.api.deleteDestination(id).subscribe(() => this.load());
    }
  }
}
